package tesoreria.compras.ordencompra.domain.model;
import org.junit.jupiter.api.Test; import tesoreria.compras.ordencompra.OrdenCompraFixture; import java.math.BigDecimal; import java.util.List; import static org.assertj.core.api.Assertions.*;
class OrdenCompraTest { @Test void calculatesAndChangesStates(){var o=OrdenCompraFixture.pendiente();assertThat(o.total()).isEqualByComparingTo("25.00");assertThat(o.transicionarA(OrdenCompraEstado.APROBADA).transicionarA(OrdenCompraEstado.ENVIADA).transicionarA(OrdenCompraEstado.CUMPLIDA).estado()).isEqualTo(OrdenCompraEstado.CUMPLIDA);assertThat(o.actualizar(o.fechaEmision(),o.proveedorId(),o.sedeId(),"x",List.of(OrdenCompraFixture.item())).observaciones()).isEqualTo("x");} @Test void rejectsInvalidItemsAndTransitions(){assertThatThrownBy(()->new OrdenCompraItem(null,"",BigDecimal.ONE,BigDecimal.ONE,1L)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->OrdenCompraFixture.pendiente().transicionarA(OrdenCompraEstado.ENVIADA)).isInstanceOf(IllegalStateException.class);assertThat(OrdenCompraEstado.ENVIADA.permite(OrdenCompraEstado.FACTURA_PARCIAL)).isTrue();assertThat(OrdenCompraEstado.ENVIADA.permite(OrdenCompraEstado.CUMPLIDA_PARCIAL)).isTrue();assertThat(OrdenCompraEstado.FACTURA_PARCIAL.permite(OrdenCompraEstado.CUMPLIDA)).isTrue();assertThat(OrdenCompraEstado.CUMPLIDA.permite(OrdenCompraEstado.ANULADA)).isFalse();} }
